\version "2.27.2"
% automatically converted by musicxml2ly from 45k-Repeats-Chords-FiguredBass.xml
\pointAndClickOff

\header {
  texidoc = "A repeat with volta brackets, also showing chord names and figured
    bass. As a specialty, the repeat at the end of measure 2 is encoded as two
    successive <barline> elements, holding a <repeat> child in the first and an
    <ending> child in the second element.

    The <figured-bass> elements in this test don't have a <duration> child."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative f' {
  \repeat volta 2 {
    \clef "treble" \numericTimeSignature \time 4/4 \key c \major f1 \alternative
    {
      \volta 1 {
        | % 1
        f1 }
      \volta 2 {
        | % 2
        f1 }
    }
  }
  | % 3
  f1 \bar "|."
}

PartPOneVoiceOneChords = \chordmode {
  \repeat volta 2 {
    c1 \alternative {
      \volta 1 {
        | % 1
        c1 }
      \volta 2 {
        | % 2
        c1 }
    }
  }
  | % 3
  c1 \bar "|."
}

PartPOneVoiceOneFiguredBass = \figuremode {
  \repeat volta 2 {
    <3>1 \alternative {
      \volta 1 {
        | % 1
        <3>1 }
      \volta 2 {
        | % 2
        <3>1 }
    }
  }
  | % 3
  <3>1 \bar "|."
}


% The score definition
\score {
  <<
    \context ChordNames = "PartPOneVoiceOneChords" {
      \PartPOneVoiceOneChords
    }
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
        \context FiguredBass = "PartPOneVoiceOneFiguredBass" \PartPOneVoiceOneFiguredBass
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
